function largestOf(numbers) {
  let ops = 0;
  let largest = numbers[0];
  for (let i = 1; i < numbers.length; i++) {
    ops++; // count the comparison
    if (numbers[i] > largest) largest = numbers[i];
  }
  return ops;
}

function countEqualPairs(numbers) {
  let ops = 0;
  let count = 0;
  for (let i = 0; i < numbers.length; i++) {
    for (let j = i + 1; j < numbers.length; j++) {
      ops++; // count the comparison
      if (numbers[i] === numbers[j]) count++;
    }
  }
  return ops;
}

const n = 10;
const list = Array.from({ length: n }, (_, k) => k);
console.log('n =', n);
console.log('largestOf comparisons:', largestOf(list));
console.log('countEqualPairs comparisons:', countEqualPairs(list));

